import{_ as t,o as s,c as a,ai as n}from"./chunks/framework.C33Uq6m-.js";const m=JSON.parse('{"title":"Comparaison de Langues -- Comprendre la Taxe de Tokens","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/language-compare.md","filePath":"fr/guide/language-compare.md"}'),o={name:"fr/guide/language-compare.md"};function r(l,e,u,i,d,p){return s(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="comparaison-de-langues-comprendre-la-taxe-de-tokens" tabindex="-1">Comparaison de Langues -- Comprendre la Taxe de Tokens <a class="header-anchor" href="#comparaison-de-langues-comprendre-la-taxe-de-tokens" aria-label="Permalink to &quot;Comparaison de Langues -- Comprendre la Taxe de Tokens&quot;">​</a></h1><p>Le preset Comparaison de Langues revele comment la meme signification coute un nombre different de tokens selon la langue dans laquelle vous l&#39;ecrivez. Ce n&#39;est pas un bug -- c&#39;est une propriete fondamentale du fonctionnement des LLMs.</p><p><strong>Page parente :</strong> <a href="./compare.html">Comparer</a><strong>Route :</strong> <code>/compare</code> (preset Comparaison de Langues)</p><h2 id="qu-est-ce-que-la-comparaison-de-langues" tabindex="-1">Qu&#39;est-ce que la Comparaison de Langues ? <a class="header-anchor" href="#qu-est-ce-que-la-comparaison-de-langues" aria-label="Permalink to &quot;Qu&#39;est-ce que la Comparaison de Langues ?&quot;">​</a></h2><p>La Comparaison de Langues est un preset de la page <a href="./compare.html">Comparer</a>. Au lieu de comparer des modeles ou des temperatures, elle compare des <strong>langues</strong>. Vous fournissez le meme prompt dans plusieurs langues et observez comment le tokenizer traite chacune d&#39;entre elles.</p><p>Cela met en evidence le <strong>biais de tokenisation</strong> -- le fait que certaines langues sont bien plus couteuses a traiter que d&#39;autres, meme lorsqu&#39;elles expriment exactement la meme idee.</p><h2 id="le-modele-mental" tabindex="-1">Le Modele Mental <a class="header-anchor" href="#le-modele-mental" aria-label="Permalink to &quot;Le Modele Mental&quot;">​</a></h2><p>Les LLMs ne comprennent pas les langues. Ils traitent des <strong>tokens</strong>.</p><p>Avant que votre texte n&#39;atteigne le modele, un <strong>tokenizer</strong> (generalement BPE -- Byte Pair Encoding) le decoupe en tokens. Le tokenizer apprend ses regles de fusion a partir des donnees d&#39;entrainement. Voici la chaine critique :</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Votre Texte  --&gt;  Tokenizer  --&gt;  Tokens  --&gt;  Modele  --&gt;  Reponse</span></span>
<span class="line"><span>   &quot;Hello&quot;         BPE         [15339]      Inference     &quot;Hi there&quot;</span></span>
<span class="line"><span>   &quot;مرحبا&quot;         BPE       [2318,112,...]  Inference     &quot;...&quot;</span></span></code></pre></div><p>L&#39;anglais domine les corpus d&#39;entrainement des LLMs. En consequence, le tokenizer apprend des fusions tres efficaces pour les mots anglais -- les mots courants deviennent souvent un seul token. Les langues moins presentes dans les donnees d&#39;entrainement (arabe, hindi, chinois, thai et bien d&#39;autres) sont <strong>fragmentees</strong> en davantage de tokens pour la meme signification.</p><p><strong>Plus de tokens signifie :</strong></p><ul><li><strong>Moins de fenetre de contexte</strong> -- Une fenetre de 4096 tokens contient moins de mots en arabe qu&#39;en anglais</li><li><strong>Generation plus lente</strong> -- Plus de tokens a produire pour une reponse equivalente</li><li><strong>Cout plus eleve</strong> -- Sur les APIs facturees au token, la meme phrase coute plus cher dans certaines langues</li><li><strong>Qualite degradee</strong> -- Le modele a moins de place pour raisonner quand le contexte est consomme par un encodage inefficace</li></ul><p>Ce n&#39;est pas une deficience d&#39;une langue quelconque. C&#39;est une consequence statistique de la distribution des donnees d&#39;entrainement. Un tokenizer entraine principalement sur du texte arabe montrerait le biais inverse.</p><h2 id="comment-l-utiliser" tabindex="-1">Comment l&#39;utiliser <a class="header-anchor" href="#comment-l-utiliser" aria-label="Permalink to &quot;Comment l&#39;utiliser&quot;">​</a></h2><ol><li><strong>Ouvrez la page Comparer</strong> et cliquez sur le bouton du preset <strong>Comparaison de Langues</strong>.</li><li><strong>Trois slots apparaissent</strong>, chacun avec un menu deroulant de langue. Les valeurs par defaut sont anglais, francais et arabe -- vous pouvez les modifier pour n&#39;importe quelle langue.</li><li><strong>Tapez ou collez votre prompt</strong> dans la zone de texte de chaque slot. Ecrivez la meme signification dans chaque langue.</li><li><strong>Detection automatique de la langue</strong> -- Le systeme detecte quelle langue vous avez reellement tapee. Si elle ne correspond pas a la langue selectionnee du slot, un bouton <strong>&quot;Traduire en X&quot;</strong> apparait pour corriger cela en un clic.</li><li><strong>Cliquez sur Comparer</strong> -- Tous les slots s&#39;executent simultanement et les resultats apparaissent cote a cote avec les metriques de Taxe de Tokens.</li></ol><p>Vous restez toujours maitre de votre prompt. Rien n&#39;est modifie ou envoye sans votre action.</p><h2 id="comprendre-les-resultats" tabindex="-1">Comprendre les Resultats <a class="header-anchor" href="#comprendre-les-resultats" aria-label="Permalink to &quot;Comprendre les Resultats&quot;">​</a></h2><p>Apres l&#39;execution de la comparaison, chaque slot affiche plusieurs metriques :</p><table tabindex="0"><thead><tr><th>Metrique</th><th>Ce que cela signifie</th></tr></thead><tbody><tr><td><strong>Tokens du Prompt</strong></td><td>Combien de tokens le tokenizer a produit a partir de votre texte d&#39;entree</td></tr><tr><td><strong>Taxe de Tokens</strong></td><td>Le ratio par rapport a la langue la plus efficace de la comparaison (generalement l&#39;anglais). Une taxe de 2.3x signifie que le prompt coute 2.3 fois plus de tokens.</td></tr><tr><td><strong>TTFT</strong></td><td>Temps jusqu&#39;au premier token. Peut etre plus eleve pour les langues qui produisent plus de tokens de prompt, car le modele doit tous les traiter avant de generer.</td></tr><tr><td><strong>Vitesse</strong></td><td>Tokens par seconde pendant la generation. Generalement similaire entre les langues car le modele genere des tokens a peu pres au meme rythme quelle que soit la langue.</td></tr><tr><td><strong>Tokens Totaux</strong></td><td>La longueur de la reponse du modele. Le modele peut produire des reponses de longueur differente selon les langues.</td></tr></tbody></table><p>La <strong>Taxe de Tokens</strong> est le chiffre cle. Elle vous indique exactement combien il est plus couteux de traiter une langue, token par token, par rapport a la reference.</p><h2 id="fonctionnalite-de-traduction" tabindex="-1">Fonctionnalite de Traduction <a class="header-anchor" href="#fonctionnalite-de-traduction" aria-label="Permalink to &quot;Fonctionnalite de Traduction&quot;">​</a></h2><p>Chaque slot inclut une capacite de traduction alimentee par votre modele Ollama local -- aucun service cloud, aucun cout.</p><ul><li><strong>La qualite depend de la taille du modele.</strong> Les modeles plus grands (7B parametres et plus) produisent des traductions nettement meilleures que les petits (3B). Si la qualite de traduction est importante, utilisez le meilleur modele dont vous disposez.</li><li><strong>Les modeles de raisonnement montrent leur travail.</strong> Si vous utilisez un modele de raisonnement comme DeepSeek-R1, vous verrez le bloc <code>&lt;think&gt;</code> pendant que le modele elabore la traduction.</li><li><strong>Vous pouvez modifier le resultat.</strong> Apres la traduction, le texte apparait dans la zone de texte du slot et vous pouvez le modifier avant de lancer la comparaison. La traduction est un point de depart, pas une reponse definitive.</li><li><strong>Un badge &quot;Traduit&quot;</strong> apparait sur le slot uniquement apres l&#39;utilisation de la traduction automatique, pour que vous sachiez toujours quels textes ont ete ecrits par un humain et lesquels ont ete traduits par la machine.</li></ul><h2 id="conseils" tabindex="-1">Conseils <a class="header-anchor" href="#conseils" aria-label="Permalink to &quot;Conseils&quot;">​</a></h2><ul><li><strong>Utilisez le meme modele pour tous les slots</strong> afin d&#39;isoler la langue comme seule variable. Si vous utilisez des modeles differents, vous ne pouvez pas determiner si les differences proviennent de la langue ou du modele.</li><li><strong>Essayez differentes tailles de modele</strong> avec le meme prompt pour voir si le ratio de taxe de tokens change. Les modeles plus grands ont parfois des vocabulaires plus etendus avec une meilleure couverture multilingue.</li><li><strong>Connectez cela au Kit Enseignants.</strong> Le <a href="./../community/educators/module-9.html">Module 9 : Ce que coutent les mots</a> fournit un plan de cours structure autour de cette fonctionnalite, avec des exercices et des questions de discussion pour une utilisation en classe.</li><li><strong>Les prompts courts amplifient l&#39;effet.</strong> Une seule phrase peut montrer des differences dramatiques de nombre de tokens. Essayez une expression courante comme &quot;Il fait beau aujourd&#39;hui&quot; dans cinq langues.</li><li><strong>Verifiez dans les deux sens.</strong> Si votre langue maternelle n&#39;est pas l&#39;anglais, essayez d&#39;abord de prompter dans votre langue -- vous constaterez peut-etre que la qualite de la reponse du modele differe, pas seulement le nombre de tokens.</li></ul><h2 id="sauvegarde-des-resultats" tabindex="-1">Sauvegarde des Resultats <a class="header-anchor" href="#sauvegarde-des-resultats" aria-label="Permalink to &quot;Sauvegarde des Resultats&quot;">​</a></h2><p>Les comparaisons sont automatiquement sauvegardees dans l&#39;IndexedDB de votre navigateur. Aucune action manuelle n&#39;est necessaire -- chaque comparaison terminee est conservee localement.</p><ul><li>Les comparaisons sauvegardees apparaissent dans le panneau <strong>&quot;Comparaisons Sauvegardees&quot;</strong> sur la page Comparer.</li><li>Cliquez sur <strong>&quot;Charger&quot;</strong> pour recharger une comparaison passee avec tous ses resultats.</li><li>Cliquez sur <strong>&quot;Supprimer&quot;</strong> pour effacer une comparaison sauvegardee.</li><li>Les donnees restent locales sur votre machine -- rien n&#39;est envoye a un serveur.</li></ul><h2 id="exportation-des-donnees" tabindex="-1">Exportation des Donnees <a class="header-anchor" href="#exportation-des-donnees" aria-label="Permalink to &quot;Exportation des Donnees&quot;">​</a></h2><p>Cliquez sur le bouton <strong>&quot;Exporter&quot;</strong> dans l&#39;en-tete des resultats pour acceder aux options d&#39;exportation :</p><ul><li><strong>Telecharger en JSON</strong> -- Donnees completes de la comparaison incluant les prompts, les sorties, les metriques et le nombre de tokens. Ideal pour une analyse approfondie dans des scripts ou des notebooks.</li><li><strong>Telecharger en Markdown</strong> -- Rapport formate avec des tableaux montrant les prompts, les resultats et les ratios de Taxe de Tokens. Pret a etre colle dans des documents ou des articles de blog.</li></ul><h2 id="partage-sur-github-discussions" tabindex="-1">Partage sur GitHub Discussions <a class="header-anchor" href="#partage-sur-github-discussions" aria-label="Permalink to &quot;Partage sur GitHub Discussions&quot;">​</a></h2><p>Cliquez sur <strong>&quot;Partager sur GitHub Discussions&quot;</strong> dans le menu Exporter pour partager vos decouvertes avec la communaute.</p><ol><li>Une boite de dialogue s&#39;ouvre avec un apercu du rapport en markdown.</li><li>Ajoutez votre propre commentaire en haut -- decrivez ce que vous avez decouvert.</li><li>Cliquez sur <strong>&quot;Ouvrir GitHub Discussions&quot;</strong> pour etre redirige vers GitHub avec le rapport pre-rempli.</li><li>Vous verifiez et soumettez la publication vous-meme -- rien n&#39;est publie sans votre consentement.</li></ol><p>Vous pouvez aussi cliquer sur <strong>&quot;Copier le Markdown&quot;</strong> pour coller le rapport ou vous le souhaitez.</p><blockquote><p><strong>Vos donnees restent locales.</strong> LLMxRay n&#39;envoie jamais les resultats de comparaison automatiquement. Le partage est toujours volontaire -- vous controlez ce qui est publie et ou.</p></blockquote>`,37)])])}const g=t(o,[["render",r]]);export{m as __pageData,g as default};
